// viz-types: custom-svg-map, ranked-bar, region-pie, rate-area | layout: fullscreen

type Tab = "map" | "deliveries" | "capacity";
type OemFilter = "all" | OemId;

const OEM_COLOR: Record<OemId, string> = {
  airbus: "#0ea5e9",
  boeing: "#f59e0b",
  comac: "#f43f5e",
