};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-xs font-semibold transition ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-100"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function project(lon: number, lat: number) {
  const x = ((lon + 180) / 360) * 100;
  const y = ((90 - lat) / 180) * 100;
  return { x, y };
}

export function CommercialAircraftAssemblyDashboard() {
  const [tab, setTab] = useState<Tab>("map");
  const [oemFilter, setOemFilter] = useState<OemFilter>("all");
  const [familyOem, setFamilyOem] = useState<"airbus" | "boeing">("airbus");
  const [hoverId, setHoverId] = useState<string | null>(null);

  const sites = useMemo(() => {
    const ranked = rankedFalSites();
    if (oemFilter === "all") return ranked;
    return ranked.filter((s) => s.oem === oemFilter);
  }, [oemFilter]);

  const deliveries = useMemo(
    () => [...OEM_DELIVERIES_2025].sort((a, b) => b.deliveries - a.deliveries),
    [],
  );

  const countries = useMemo(
    () => [...FAL_BY_COUNTRY].sort((a, b) => b.lines - a.lines),
    [],
  );

  const regions = useMemo(
    () => [...FAL_BY_REGION].sort((a, b) => b.lines - a.lines),
    [],
  );

  const familyData = useMemo(() => {
    const rows =
      familyOem === "airbus" ? AIRBUS_2025_BY_FAMILY : BOEING_2025_BY_FAMILY;
    return [...rows].sort((a, b) => b.deliveries - a.deliveries);
  }, [familyOem]);

  const hoverSite = hoverId
    ? FAL_SITES.find((s) => s.id === hoverId) ?? null
    : null;

  return (
    <div data-viz className="space-y-6">
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-6 text-white sm:px-8">
        <p className="text-xs font-semibold uppercase tracking-[0.2em] text-sky-300">
          Commercial aircraft final assembly ??? OEM footprints

/**
 * QA: fiscal-plumbing-research-2026
 * // viz-types: ranked lollipop bars, cumulative area, family bars, treasury???JCT grouped bars, budget yardstick bars | layout: canvas
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  HEADLINE,
  JCT_TOP10,
  TREASURY_HEADLINES,
  rankedJctTop10,
} from "../src/data/fiscal-plumbing-research-2026-data.ts";

assert.equal(HEADLINE.jctFy2026Tn, 2.3);
assert.equal(HEADLINE.treasuryEsiBn, 296);
assert.equal(HEADLINE.jctEsiBn, 240);
assert.equal(JCT_TOP10.length, 10);
assert.equal(TREASURY_HEADLINES.length, 4);
const ranked = rankedJctTop10();
assert.equal(ranked[0].shortLabel, "Pensions / retirement");
assert.ok(ranked[0].fy2026Bn >= ranked[1].fy2026Bn);

const root = process.cwd();
const slug = "fiscal-plumbing-research-2026";
const markers = [
  "Fiscal plumbing ??? tax expenditures as off-budget spend",
  "JCT largest tax expenditures",
];

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4191);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "networkidle",
      timeout: 45000,
    });
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({ timeout: 20000 });
      console.log(`??? ${m}`);
    }
    for (const label of ["Top-N build-up", "By family", "Treasury ??? JCT", "Budget scale", "Ranked cost"]) {
      const btn = page.getByRole("button", { name: label });
      if (await btn.count()) {
        await btn.first().click();
        await page.waitForTimeout(400);
      }
    }
    await page.getByRole("button", { name: "Ranked cost" }).first().click();
    await page.getByRole("button", { name: "Treasury headlines" }).first().click();
    await page.getByText("Treasury published FY2026 headline items", { exact: false }).first().waitFor({
      timeout: 10000,
    });
    console.log("??? Treasury scope toggle");
    const audit = await auditVizInteractions(page);
    if (audit.issues?.length) {
      console.error("??? Viz interaction audit failed", audit);
      process.exit(1);
    }
    if (audit.warnings?.length) {
      console.log("??? warnings:", audit.warnings.join("; "));
    }
    console.log(`??? QA passed: ${slug}`);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

