    type Rect = {
      x: number;
      y: number;
      w: number;
      h: number;
      country: string;
      shortLabel: string;
      value: number;
      share: number;
      color: string;
    };
    const rects: Rect[] = [];
    let x = 0;
    let remainingW = W;
    let i = 0;
    // Simple strip packing: first item (China) takes full-height strip, rest stack
    if (items.length) {
      const first = items[0];
      const fw = (first.value / total) * W;
      rects.push({
        x: 0,
        y: 0,
        w: fw,
        h: H,
        country: first.country,
        shortLabel: first.shortLabel,
        value: first.value,
        share: (first.value / total) * 100,
        color: first.color,
      });
      x = fw;
      remainingW = W - fw;
      i = 1;
    }
    let cy = 0;
    const rest = items.slice(i);
    const restTotal = rest.reduce((s, r) => s + r.value, 0) || 1;
    for (const it of rest) {
      const h = (it.value / restTotal) * H;
      rects.push({
        x,
        y: cy,
        w: remainingW,
        h: Math.max(h, 18),
        country: it.country,
        shortLabel: it.shortLabel,
        value: it.value,
        share: (it.value / total) * 100,
        color: it.color,
      });
      cy += h;
    }
    // Normalize last heights if overflow
    const overflow = cy - H;
    if (overflow > 0 && rects.length > 1) {
      rects[rects.length - 1].h = Math.max(
        18,
        rects[rects.length - 1].h - overflow,
      );
    }
    return { rects, W, H };
  }, [rows]);

  return (
