args.streamContent:
"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  DELIVERIES_2024,
  EAST_ASIA_SHARE_PATH,
  HEADLINE,
  OWN_VS_BUILD,
  PIPELINE_METRICS,
  RECYCLING_2024,
  SEGMENT_DELIVERIES,
  SOURCE_NOTE,
  SOURCES,
  fmtGt,
  fmtPct,
  rankedDeliveries,
  type SegmentId,
} from "@/data/global-shipbuilding-gt-delivery-concentration-2026-data";

// viz-types: ranked-bar, stacked-area, own-vs-build scatter, segment stacked-bar, pipeline grouped-bar, recycling donut | layout: default

type Tab = "deliveries" | "trajectory" | "ownbuild" | "segments" | "pipeline";
type RankMode = "share" | "gt";
type PipelineMode = "deliveries" | "contracts" | "orderbook";
type SegmentScope = "all" | SegmentId;

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-xs font-semibold transition ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-100"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function GlobalShipbuildingGtDeliveryDashboard() {
  const [tab, setTab] = useState<Tab>("deliveries");
  const [rankMode, setRankMode] = useState<RankMode>("share");
  const [pipelineMode, setPipelineMode] = useState<PipelineMode>("deliveries");
  const [segmentScope, setSegmentScope] = useState<SegmentScope>("all");
  const [hoverEconomy, setHoverEconomy] = useState<string | null>(null);

  const ranked = useMemo(() => rankedDeliveries(rankMode), [rankMode]);

  const segmentRows = useMemo(() => {
    const rows =
      segmentScope === "all"
        ? SEGMENT_DELIVERIES
        : SEGMENT_DELIVERIES.filter((s) => s.id === segmentScope);
    return rows.map((s) => ({
      segment: s.segment,
      China: s.chinaGtThousand,
      Korea: s.koreaGtThousand,
      Japan: s.japanGtThousand,
      Other: s.otherGtThousand,
      total: s.totalGtThousand,
      worldSharePct: s.worldSharePct,
    }));
  }, [segmentScope]);

  const pipelineRow = useMemo(() => {
    const m = PIPELINE_METRICS.find((p) => p.id === pipelineMode)!;
    return [
      { builder: "China", share: m.china, color: "#f43f5e" },
      { builder: "Korea", share: m.korea, color: "#0ea5e9" },
      { builder: "Japan", share: m.japan, color: "#f59e0b" },
      { builder: "Other", share: m.other, color: "#94a3b8" },
    ];
  }, [pipelineMode]);

  const hoverOwn = hoverEconomy
    ? OWN_VS_BUILD.find((r) => r.shortLabel === hoverEconomy) ?? null
    : null;

  return (
    <div data-viz className="space-y-6">
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-6 text-white sm:px-8">
        <p className="text-xs font-semibold uppercase tracking-[0.2em] text-rose-300">
          Global shipbuilding GT delivery concentration
        </p>
        <h2 className="mt-2 text-2xl font-bold tracking-tight sm:text-3xl">
          China delivered {fmtPct(HEADLINE.chinaDeliveryShare2024)} of world
          merchant GT in 2024
        </h2>
        <p className="mt-3 max-w-3xl text-sm leading-relaxed text-slate-300">
          East Asia&apos;s trio ??? China, Korea, Japan ??? finished{" "}
          {fmtPct(HEADLINE.eastAsiaTrioShare2024, 0)} of new merchant gross
          tonnage. Greece still owns the largest fleet by deadweight, while the
          United States builds roughly {fmtPct(HEADLINE.usBuildShare2024, 2)} of
          commercial GT. Ownership and construction are different maps.
        </p>
        <p className="mt-2 text-xs text-slate-400">{SOURCE_NOTE}</p>
      </div>

