                    />
                    <YAxis
                      type="category"
                      dataKey="shortLabel"
                      width={88}
                      tick={{ fontSize: 11, fill: "#334155" }}
                    />
                    <Tooltip
                      formatter={(value: number) =>
                        rankMode === "share"
                          ? fmtPct(value)
                          : fmtGt(value)
