                <XAxis
                  dataKey="year"
                  tick={{ fontSize: 11, fill: "#64748b" }}
                />
                <YAxis
                  tick={{ fontSize: 11, fill: "#64748b" }}
                  tickFormatter={(v) => `${v}%`}
                  domain={[0, 100]}
                />
                <Tooltip
                  formatter={(v: number, name: string) => [
                    fmtPct(v),
                    name,
                  ]}
                />
                <Area
                  type="monotone"
                  dataKey="china"
                  stackId="1"
                  stroke="#f43f5e"
                  fill="#f43f5e"
                  fillOpacity={0.85}
                  name="China"
                />
                <Area
                  type="monotone"
                  dataKey="korea"
                  stackId="1"
                  stroke="#0ea5e9"
                  fill="#0ea5e9"
                  fillOpacity={0.8}
                  name="Korea"
                />
                <Area
                  type="monotone"
                  dataKey="japan"
                  stackId="1"
                  stroke="#f59e0b"
                  fill="#f59e0b"
                  fillOpacity={0.8}
                  name="Japan"
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-3 text-xs text-slate-500">
            UNCTAD: China crossed ~50% of world GT output for the first time in
            2023, then {fmtPct(HEADLINE.chinaDeliveryShare2024)} in 2024.
          </p>
        </ChartCard>
      )}

      {tab === "ownbuild" && (
        <div className="grid gap-6 lg:grid-cols-5">
          <div className="lg:col-span-3">
            <ChartCard
              title="Who owns the fleet vs who builds new GT"
              subtitle="X = beneficial ownership share (dwt, Jan 2025) ?? Y = 2024 GT delivery share"
            >
              <div className="h-[420px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <ScatterChart
                    margin={{ top: 16, right: 24, left: 8, bottom: 24 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      type="number"
                      dataKey="ownShareDwt"
                      name="Own %"
                      unit="%"
                      tick={{ fontSize: 11, fill: "#64748b" }}
                      label={{
                        value: "Ownership share (dwt %)",
                        position: "insideBottom",
                        offset: -12,
                        style: { fontSize: 11, fill: "#64748b" },
                      }}
                    />
                    <YAxis
                      type="number"
                      dataKey="buildShareGt"
                      name="Build %"
                      unit="%"
                      tick={{ fontSize: 11, fill: "#64748b" }}
                      label={{
                        value: "Build share (GT %)",
                        angle: -90,
                        position: "insideLeft",
                        style: { fontSize: 11, fill: "#64748b" },
                      }}
                    />
                    <ZAxis range={[80, 80]} />
                    <Tooltip
                      cursor={{ strokeDasharray: "3 3" }}
                      formatter={(v: number, name: string) => [
                        fmtPct(v),
                        name === "ownShareDwt" ? "Own (dwt)" : "Build (GT)",
                      ]}
                      labelFormatter={(_, payload) =>
                        payload?.[0]?.payload?.economy ?? ""
                      }
                    />
                    <Scatter
                      data={OWN_VS_BUILD}
                      onMouseEnter={(d) =>
                        setHoverEconomy(
                          (d as { shortLabel?: string }).shortLabel ?? null,
                        )
                      }
                      onMouseLeave={() => setHoverEconomy(null)}
                    >
                      {OWN_VS_BUILD.map((r) => (
                        <Cell
                          key={r.id}
                          fill={r.color}
                          stroke={
                            hoverEconomy === r.shortLabel ? "#0f172a" : r.color
                          }
                          strokeWidth={hoverEconomy === r.shortLabel ? 2 : 1}
                        />
                      ))}
                    </Scatter>
                  </ScatterChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
          <div className="lg:col-span-2">
            <ChartCard
              title={hoverOwn ? hoverOwn.economy : "Read the diagonal"}
              subtitle={
                hoverOwn
                  ? `Own ${fmtPct(hoverOwn.ownShareDwt)} ?? Build ${fmtPct(hoverOwn.buildShareGt)}`
                  : "Hover a point ??? builders sit high; pure owners sit right"
              }
            >
              <p className="text-sm leading-relaxed text-slate-600">
                {hoverOwn
                  ? hoverOwn.note
                  : `Greece owns ${fmtPct(HEADLINE.greeceOwnShareDwt2025)} of world dwt capacity but barely appears on the delivery axis. China owns ${fmtPct(HEADLINE.chinaOwnShareDwt2025)} yet builds ${fmtPct(HEADLINE.chinaDeliveryShare2024)}. Korea builds far more than it owns ??? the high-value specialist.`}
              </p>
              <ul className="mt-4 space-y-2 text-xs text-slate-600">
                {OWN_VS_BUILD.slice(0, 5).map((r) => (
                  <li
                    key={r.id}
                    className="flex cursor-default items-center justify-between gap-2 rounded-md px-2 py-1 hover:bg-slate-50"
