/**
 * Global shipbuilding GT delivery concentration ??? UNCTAD RMT 2025 / Clarksons.
 * Deliveries = completed merchant tonnage by country of build (gross tons).
 * Ownership = beneficial ownership of fleet capacity (deadweight tons).
 */

export const HEADLINE = {
  chinaDeliveryShare2024: 54.57,
  koreaDeliveryShare2024: 28.02,
  japanDeliveryShare2024: 12.56,
  eastAsiaTrioShare2024: 95.15,
  chinaContractShare2024: 74.4,
  chinaOrderbookShareStart2025: 63.7,
  worldDeliveriesMillionGt2024: 71.69,
  chinaOwnShareDwt2025: 14.4,
  greeceOwnShareDwt2025: 16.4,
  usBuildShare2024: 0.04,
  activeYards2024: 348,
  chinaYardsActive: 120,
} as const;

export const SOURCES = [
  "UNCTAD ??? Review of Maritime Transport 2025, Chapter II (Table II.1 shipbuilding shares; Table II.3 ownership; Table II.6 deliveries by type)",
