"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  DELIVERIES_2024,
  EAST_ASIA_SHARE_PATH,
  HEADLINE,
  OWN_VS_BUILD,
  PIPELINE_METRICS,
  RECYCLING_2024,
  SEGMENT_DELIVERIES,
  SOURCE_NOTE,
  SOURCES,
  fmtGt,
  fmtPct,
  rankedDeliveries,
  type SegmentId,
} from "@/data/global-shipbuilding-gt-delivery-concentration-2026-data";

// viz-types: ranked-bar, stacked-area, own-vs-build scatter, segment stacked-bar, pipeline grouped-bar, recycling donut | layout: default

type Tab = "deliveries" | "trajectory" | "ownbuild" | "segments" | "pipeline";
type RankMode = "share" | "gt";
type PipelineMode = "deliveries" | "contracts" | "orderbook";
type SegmentScope = "all" | SegmentId;

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-xs font-semibold transition ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-100"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

