        {tab === "segments" && (
          <ToggleGroup
            label="Segment"
            value={segmentScope}
            onChange={setSegmentScope}
            options={[
              { id: "all", label: "All" },
              { id: "container", label: "Container" },
              { id: "bulk", label: "Bulkers" },
              { id: "gas", label: "Gas" },
              { id: "tanker", label: "Tankers" },
            ]}
          />
        )}
        {tab === "pipeline" && (
          <ToggleGroup
            label="Meter"
            value={pipelineMode}
            onChange={setPipelineMode}
            options={[
              { id: "deliveries", label: "Deliveries" },
              { id: "contracts", label: "2024 contracts" },
              { id: "orderbook", label: "Orderbook" },
            ]}
          />
        )}
      </div>

      {tab === "deliveries" && (
        <div className="grid gap-6 lg:grid-cols-5">
          <div className="lg:col-span-3">
            <ChartCard
              title="Who delivered new merchant GT in 2024"
              subtitle="UNCTAD Table II.1 / II.6 ??? propelled seagoing vessels ???100 GT"
            >
              <div className="h-[420px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={ranked}
                    layout="vertical"
                    margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      type="number"
                      tick={{ fontSize: 11, fill: "#64748b" }}
                      tickFormatter={(v) =>
                        rankMode === "share" ? `${v}%` : `${v}`
                      }
                    />
                    <YAxis
                      type="category"
                      dataKey="shortLabel"
                      width={88}
                      tick={{ fontSize: 11, fill: "#334155" }}
                    />
                    <Tooltip
                      formatter={(value: number) =>
                        rankMode === "share"
                          ? fmtPct(value)
                          : fmtGt(value)
                      }
                      labelFormatter={(l) => String(l)}
                    />
                    <Bar
                      dataKey={rankMode === "share" ? "sharePct" : "gtThousand"}
                      radius={[0, 4, 4, 0]}
                      name={rankMode === "share" ? "Share of GT" : "Thousand GT"}
                    >
                      {ranked.map((r) => (
                        <Cell key={r.id} fill={r.color} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
          <div className="lg:col-span-2 space-y-6">
            <ChartCard
              title="East Asia vs everyone else"
              subtitle={`Trio share ${fmtPct(HEADLINE.eastAsiaTrioShare2024)}`}
            >
              <div className="h-[220px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={[
                        {
                          name: "China",
                          value: HEADLINE.chinaDeliveryShare2024,
                          color: "#f43f5e",
                        },
                        {
                          name: "Korea",
                          value: HEADLINE.koreaDeliveryShare2024,
                          color: "#0ea5e9",
                        },
                        {
                          name: "Japan",
                          value: HEADLINE.japanDeliveryShare2024,
                          color: "#f59e0b",
                        },
                        {
                          name: "Rest",
                          value: 100 - HEADLINE.eastAsiaTrioShare2024,
                          color: "#cbd5e1",
                        },
                      ]}
                      dataKey="value"
                      nameKey="name"
                      cx="50%"
                      cy="50%"
                      innerRadius={48}
                      outerRadius={78}
                      paddingAngle={2}
                    >
                      {[
                        "#f43f5e",
                        "#0ea5e9",
                        "#f59e0b",
                        "#cbd5e1",
                      ].map((c) => (
                        <Cell key={c} fill={c} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(v: number) => fmtPct(v)} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
              <ul className="mt-2 space-y-1 text-xs text-slate-600">
                {DELIVERIES_2024.slice(0, 3).map((r) => (
                  <li key={r.id} className="flex justify-between gap-2">
                    <span className="font-medium text-slate-800">
                      {r.shortLabel}
                    </span>
                    <span>
                      {fmtPct(r.sharePct)} ?? {fmtGt(r.gtThousand)}
                    </span>
                  </li>
                ))}
              </ul>
            </ChartCard>
            <div className="rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-600">
              <p className="font-semibold text-slate-900">
                {HEADLINE.worldDeliveriesMillionGt2024}M GT delivered worldwide
              </p>
              <p className="mt-1 text-xs leading-relaxed">
                About {HEADLINE.activeYards2024} yards booked or delivered in
                2024 ??? half the 2007 peak. China&apos;s ~{HEADLINE.chinaYardsActive}{" "}
                active yards hold ~45% of global yard capacity and ~60% of the
                orderbook.
              </p>
            </div>
          </div>
        </div>
      )}

      {tab === "trajectory" && (
        <ChartCard
          title="East Asia builder shares over a decade"
          subtitle="2023???24 China/Korea/Japan from UNCTAD; earlier years directional (rounded industry path)"
        >
          <div className="h-[400px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart
                data={EAST_ASIA_SHARE_PATH}
                margin={{ top: 12, right: 16, left: 0, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="year"
                  tick={{ fontSize: 11, fill: "#64748b" }}
                />
                <YAxis
                  tick={{ fontSize: 11, fill: "#64748b" }}
                  tickFormatter={(v) => `${v}%`}
                  domain={[0, 100]}
                />
                <Tooltip
                  formatter={(v: number, name: string) => [
                    fmtPct(v),
                    name,
                  ]}
                />
                <Area
                  type="monotone"
                  dataKey="china"
                  stackId="1"
                  stroke="#f43f5e"
                  fill="#f43f5e"
                  fillOpacity={0.85}
                  name="China"
                />
                <Area
                  type="monotone"
                  dataKey="korea"
                  stackId="1"
                  stroke="#0ea5e9"
                  fill="#0ea5e9"
                  fillOpacity={0.8}
                  name="Korea"
                />
                <Area
                  type="monotone"
                  dataKey="japan"
                  stackId="1"
                  stroke="#f59e0b"
                  fill="#f59e0b"
                  fillOpacity={0.8}
                  name="Japan"
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-3 text-xs text-slate-500">
            UNCTAD: China crossed ~50% of world GT output for the first time in
            2023, then {fmtPct(HEADLINE.chinaDeliveryShare2024)} in 2024.
          </p>
        </ChartCard>
      )}

      {tab === "ownbuild" && (
        <div className="grid gap-6 lg:grid-cols-5">
          <div className="lg:col-span-3">
            <ChartCard
              title="Who owns the fleet vs who builds new GT"
              subtitle="X = beneficial ownership share (dwt, Jan 2025) ?? Y = 2024 GT delivery share"
            >
              <div className="h-[420px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <ScatterChart
                    margin={{ top: 16, right: 24, left: 8, bottom: 24 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      type="number"
                      dataKey="ownShareDwt"
                      name="Own %"
                      unit="%"
                      tick={{ fontSize: 11, fill: "#64748b" }}
                      label={{
                        value: "Ownership share (dwt %)",
                        position: "insideBottom",
                        offset: -12,
                        style: { fontSize: 11, fill: "#64748b" },
                      }}
                    />
                    <YAxis
                      type="number"
                      dataKey="buildShareGt"
                      name="Build %"
                      unit="%"
                      tick={{ fontSize: 11, fill: "#64748b" }}
                      label={{
                        value: "Build share (GT %)",
                        angle: -90,
                        position: "insideLeft",
                        style: { fontSize: 11, fill: "#64748b" },
                      }}
                    />
                    <ZAxis range={[80, 80]} />
                    <Tooltip
                      cursor={{ strokeDasharray: "3 3" }}
                      formatter={(v: number, name: string) => [
                        fmtPct(v),
                        name === "ownShareDwt" ? "Own (dwt)" : "Build (GT)",
                      ]}
                      labelFormatter={(_, payload) =>
                        payload?.[0]?.payload?.economy ?? ""
                      }
                    />
                    <Scatter
                      data={OWN_VS_BUILD}
                      onMouseEnter={(d) =>
                        setHoverEconomy(
                          (d as { shortLabel?: string }).shortLabel ?? null,
                        )
                      }
                      onMouseLeave={() => setHoverEconomy(null)}
                    >
                      {OWN_VS_BUILD.map((r) => (
                        <Cell
                          key={r.id}
                          fill={r.color}
                          stroke={
                            hoverEconomy === r.shortLabel ? "#0f172a" : r.color
                          }
                          strokeWidth={hoverEconomy === r.shortLabel ? 2 : 1}
                        />
                      ))}
                    </Scatter>
                  </ScatterChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
          <div className="lg:col-span-2">
            <ChartCard
              title={hoverOwn ? hoverOwn.economy : "Read the diagonal"}
              subtitle={
                hoverOwn
                  ? `Own ${fmtPct(hoverOwn.ownShareDwt)} ?? Build ${fmtPct(hoverOwn.buildShareGt)}`
                  : "Hover a point ??? builders sit high; pure owners sit right"
              }
            >
              <p className="text-sm leading-relaxed text-slate-600">
                {hoverOwn
                  ? hoverOwn.note
                  : `Greece owns ${fmtPct(HEADLINE.greeceOwnShareDwt2025)} of world dwt capacity but barely appears on the delivery axis. China owns ${fmtPct(HEADLINE.chinaOwnShareDwt2025)} yet builds ${fmtPct(HEADLINE.chinaDeliveryShare2024)}. Korea builds far more than it owns ??? the high-value specialist.`}
              </p>
              <ul className="mt-4 space-y-2 text-xs text-slate-600">
                {OWN_VS_BUILD.slice(0, 5).map((r) => (
                  <li
                    key={r.id}
                    className="flex cursor-default items-center justify-between gap-2 rounded-md px-2 py-1 hover:bg-slate-50"
                    onMouseEnter={() => setHoverEconomy(r.shortLabel)}
                    onMouseLeave={() => setHoverEconomy(null)}
                  >
                    <span
                      className="font-semibold"
                      style={{ color: r.color }}
                    >
                      {r.shortLabel}
                    </span>
                    <span>
                      O {fmtPct(r.ownShareDwt, 1)} / B{" "}
                      {fmtPct(r.buildShareGt, 1)}
                    </span>
                  </li>
                ))}
              </ul>
            </ChartCard>
          </div>
        </div>
      )}

      {tab === "segments" && (
        <ChartCard
          title="2024 deliveries by ship type ??? who finishes which hull"
          subtitle="Stacked thousand GT ?? Korea leads gas carriers; China leads containers & bulkers"
        >
          <div className="h-[400px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={segmentRows}
                margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="segment"
                  tick={{ fontSize: 10, fill: "#64748b" }}
                  interval={0}
                  angle={-18}
                  textAnchor="end"
                  height={70}
                />
                <YAxis
                  tick={{ fontSize: 11, fill: "#64748b" }}
                  tickFormatter={(v) => `${(v / 1000).toFixed(0)}M`}
                />
                <Tooltip
                  formatter={(v: number, name: string) => [fmtGt(v), name]}
                />
                <Bar dataKey="China" stackId="a" fill="#f43f5e" />
                <Bar dataKey="Korea" stackId="a" fill="#0ea5e9" />
                <Bar dataKey="Japan" stackId="a" fill="#f59e0b" />
                <Bar
                  dataKey="Other"
                  stackId="a"
                  fill="#94a3b8"
                  radius={[4, 4, 0, 0]}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Containers were {fmtPct(41.3)} of world GT delivered in 2024;
            bulkers {fmtPct(26.6)}; gas carriers {fmtPct(12.2)}. Gas is the only
            major cargo segment where Korea ??? not China ??? holds the majority of
            deliveries.
          </p>
        </ChartCard>
      )}

      {tab === "pipeline" && (
        <div className="grid gap-6 lg:grid-cols-5">
          <div className="lg:col-span-3">
            <ChartCard
              title="Deliveries ??? contracts ??? orderbook"
              subtitle={
                PIPELINE_METRICS.find((p) => p.id === pipelineMode)?.unit
              }
            >
              <div className="h-[360px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={pipelineRow}
                    margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      dataKey="builder"
                      tick={{ fontSize: 12, fill: "#334155" }}
                    />
                    <YAxis
                      tick={{ fontSize: 11, fill: "#64748b" }}
                      tickFormatter={(v) => `${v}%`}
                      domain={[0, 80]}
                    />
                    <Tooltip formatter={(v: number) => fmtPct(v)} />
                    <Bar dataKey="share" radius={[6, 6, 0, 0]} name="Share">
                      {pipelineRow.map((r) => (
                        <Cell key={r.builder} fill={r.color} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
              <p className="mt-2 text-xs text-slate-500">
                China&apos;s disclosed prints: {fmtPct(HEADLINE.chinaDeliveryShare2024)}{" "}
                of 2024 deliveries, {fmtPct(HEADLINE.chinaContractShare2024)} of
                2024 contracted GT, and{" "}
                {fmtPct(HEADLINE.chinaOrderbookShareStart2025)} of the orderbook
                at start-2025. Peer bars for contracts/orderbook are residual
                approximations so the stack reads as 100%.
              </p>
            </ChartCard>
          </div>
          <div className="lg:col-span-2">
            <ChartCard
              title="Where ships die ??? recycling 2024"
              subtitle="91.7% of scrap GT in Bangladesh, India, Pakistan & T??rkiye"
            >
              <div className="h-[260px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={RECYCLING_2024}
                      dataKey="sharePct"
                      nameKey="economy"
                      cx="50%"
                      cy="50%"
                      innerRadius={42}
                      outerRadius={72}
                    >
                      {RECYCLING_2024.map((r) => (
                        <Cell key={r.economy} fill={r.color} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(v: number) => fmtPct(v)} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
              <ul className="space-y-1 text-xs text-slate-600">
                {RECYCLING_2024.slice(0, 4).map((r) => (
                  <li key={r.economy} className="flex justify-between">
                    <span>{r.economy}</span>
                    <span className="font-medium">{fmtPct(r.sharePct)}</span>
                  </li>
                ))}
              </ul>
            </ChartCard>
          </div>
        </div>
      )}

      <details className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-600">
        <summary className="cursor-pointer font-semibold text-slate-800">
          Sources
        </summary>
        <ul className="mt-2 list-disc space-y-1 pl-5 text-xs">
          {SOURCES.map((s) => (
            <li key={s}>{s}</li>
          ))}
        </ul>
      </details>
    </div>
  );
}

